(function () {
  'use strict';

  // ------------------------------------------------------------
  // Configuration
  // ------------------------------------------------------------
  var WORKER_BASE_URL = 'https://<MY_WORKER_URL>';         // e.g. 'https://px-api.your-name.workers.dev'
  var MATCH_FILTERS = '[]/[]/["8634"]';
  var TEAM_LOGO_BASE = 'https://imgs.ysscores.com/teams/128/';
  var LEAGUE_LOGO_BASE = 'https://imgs.ysscores.com/championship/64/';
  var MAX_ATTEMPTS = 3;                                     // fetch attempts before showing an error
  var REFRESH_MS = 60 * 1000;                               // silent refresh of today's scores
  var LIVE_WINDOW_MS = 3.5 * 60 * 60 * 1000;

  var DEFAULT_LOGO_URL = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64">' +
    '<path d="M32 4 8 12v18c0 15 10.5 25.5 24 30 13.5-4.5 24-15 24-30V12L32 4z" fill="#32CD32" fill-opacity=".18" stroke="#32CD32" stroke-width="3"/>' +
    '<circle cx="32" cy="30" r="8" fill="none" stroke="#32CD32" stroke-width="3"/></svg>');
  window.PXL_DEFAULT_LOGO = DEFAULT_LOGO_URL;

  // Where a click on a match card goes. '' = cards are not links. Example: '/p/match.html'
  var MATCH_PAGE_URL = '';

  var NOT_CONFIGURED = WORKER_BASE_URL.indexOf('<MY_WORKER_URL>') !== -1;

  // ------------------------------------------------------------
  // Helpers
  // ------------------------------------------------------------
  var ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  function esc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return ESC[c]; }); }
  function wait(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }

  async function fetchJson(url, attempts) {
    if (attempts == null) attempts = MAX_ATTEMPTS;
    for (var i = 1; ; i++) {
      var controller = new AbortController();
      var timeout = setTimeout(function () { controller.abort(); }, 9000);
      try {
        var resp = await fetch(url, { signal: controller.signal, headers: { Accept: 'application/json' } });
        if (!resp.ok) throw new Error('HTTP ' + resp.status);
        var json = await resp.json();
        if (json && json.status === false) throw new Error('API error: ' + (json.message || 'status false'));
        return json;
      } catch (e) {
        if (i >= attempts) throw e;
        await wait(1000 * i);                               // 1s, 2s ... between attempts
      } finally {
        clearTimeout(timeout);
      }
    }
  }

  function cairoDateString(dateObj) {
    var parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo' }).formatToParts(dateObj);
    var get = function (t) { return parts.find(function (p) { return p.type === t; }).value; };
    return get('year') + '-' + get('month') + '-' + get('day');
  }
  function cairoTime(unixSeconds) {
    var d = new Date(Number(unixSeconds) * 1000);
    if (!unixSeconds || isNaN(d)) return '--:--';
    return new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit', hour12: false }).format(d);
  }

  function matchesUrl(isoDate) {
    return WORKER_BASE_URL + '/api/matches/matches_date_get/' + isoDate + '/' + encodeURI(MATCH_FILTERS) + '/D/60';
  }
  function matchInfoUrl(id) {
    return WORKER_BASE_URL + '/api/matches/match_info/' + encodeURIComponent(id) + '/D/60';
  }

  function imageUrl(base, file) {
    var f = file ? String(file).trim() : '';
    return /^[\w.-]+\.(png|jpe?g|webp|gif|svg)$/i.test(f) ? base + encodeURIComponent(f) : '';
  }

  function category(raw) {
    var s = Number(raw.status);
    if (s === 0) return 'upcoming';
    if (s === 4) return 'finished';
    var kickoff = Number(raw.match_timestamp) * 1000;
    var now = Date.now();
    if (kickoff && now >= kickoff - 10 * 60 * 1000 && now <= kickoff + LIVE_WINDOW_MS) return 'live';
    return 'other';
  }

  function normalize(raw) {
    var cc = Array.isArray(raw.channel_commm) && raw.channel_commm.length ? raw.channel_commm[0] : {};
    var champ = raw.championship || {};
    var home = raw.home_team || {};
    var away = raw.away_team || {};
    return {
      id: raw.match_id,
      timestamp: Number(raw.match_timestamp) || 0,
      champKey: String(raw.championship_id != null ? raw.championship_id : (champ.title || '')),
      league: champ.title || 'مباريات',
      leagueLogo: imageUrl(LEAGUE_LOGO_BASE, champ.image),
      cat: category(raw),
      minute: Number(raw.minutes) > 0 ? Number(raw.minutes) : 0,
      time: cairoTime(raw.match_timestamp),
      home: { name: home.full_title || home.title || '', logo: imageUrl(TEAM_LOGO_BASE, home.image) || DEFAULT_LOGO_URL },
      away: { name: away.full_title || away.title || '', logo: imageUrl(TEAM_LOGO_BASE, away.image) || DEFAULT_LOGO_URL },
      scoreHome: raw.home_scores != null ? raw.home_scores : 0,
      scoreAway: raw.away_scores != null ? raw.away_scores : 0,
      channel: cc.channel_name || 'غير متوفر',
      commentator: cc.commentator_name || 'غير متوفر'
    };
  }

  // Group by championship, keeping the API's league order; kickoff order inside a league
  function groupByLeague(list) {
    var order = [];
    var groups = {};
    list.forEach(function (m) {
      if (!groups[m.champKey]) {
        groups[m.champKey] = { league: m.league, logo: m.leagueLogo, matches: [] };
        order.push(m.champKey);
      }
      groups[m.champKey].matches.push(m);
    });
    return order.map(function (k) {
      groups[k].matches.sort(function (a, b) { return a.timestamp - b.timestamp; });
      return groups[k];
    });
  }

  // ------------------------------------------------------------
  // State & rendering
  // ------------------------------------------------------------
  var container = document.getElementById('matches-api-container');
  var tabs = document.querySelectorAll('#matchTabs .tab');
  var searchInput = document.getElementById('matchSearch');
  var todayLabel = document.getElementById('todayLabel');
  if (!container) return;

  var state = { date: new Date(), filter: 'all', matches: [], loaded: false, requestId: 0 };
  var liveInfoCache = {};

  var ICON_TV = '<svg aria-hidden="true" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="2" y="7" width="20" height="15" rx="2" ry="2" stroke-width="2"></rect><polyline points="17 2 12 7 7 2" stroke-width="2"></polyline></svg>';
  var ICON_MIC = '<svg aria-hidden="true" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11a7 7 0 01-14 0m7 7v4m-4 0h8M12 1a3 3 0 00-3 3v8a3 3 0 006 0V4a3 3 0 00-3-3z"></path></svg>';

  function countLabel(n) {
    if (n === 1) return 'مباراة واحدة';
    if (n === 2) return 'مباراتان';
    if (n >= 3 && n <= 10) return n + ' مباريات';
    return n + ' مباراة';
  }
  function logoImg(team) {
    return `<img src="${esc(team.logo)}" alt="${esc(team.name)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.onerror=null;this.src=window.PXL_DEFAULT_LOGO">`;
  }
  function scoreHtml(m) {
    return `<span>${esc(m.scoreHome)}</span><span class="sep">-</span><span>${esc(m.scoreAway)}</span>`;
  }
  function cardLink(m) {
    return MATCH_PAGE_URL && m.id != null ? MATCH_PAGE_URL + '?id=' + encodeURIComponent(m.id) : '';
  }

  function matchCard(m) {
    var isLive = m.cat === 'live';
    var isFinished = m.cat === 'finished';
    var link = cardLink(m);
    var statusText = isLive ? 'مباشر' + (m.minute ? ' ' + m.minute + "'" : '')
      : isFinished ? 'انتهت'
      : m.cat === 'other' ? 'غير محدد'
      : 'لم تبدأ';
    return `
      <article class="match-card${isLive ? ' is-live' : ''}${link ? ' is-link' : ''}"${link ? ` data-href="${esc(link)}" role="link" tabindex="0"` : ''}>
        <div class="match-card__body">
          <div class="match-team">
            ${logoImg(m.home)}
            <div class="match-team__name">${esc(m.home.name)}</div>
          </div>
          <div class="match-mid">
            <div class="match-badge">${isLive || isFinished ? scoreHtml(m) : `<span class="time">${esc(m.time)}</span>`}</div>
            <span class="match-status">${esc(statusText)}</span>
          </div>
          <div class="match-team">
            ${logoImg(m.away)}
            <div class="match-team__name">${esc(m.away.name)}</div>
          </div>
        </div>
        <div class="match-card__footer">
          <div class="match-meta match-meta--channel">${ICON_TV}<span>${esc(m.channel)}</span></div>
          <div class="match-meta match-meta--commentator">${ICON_MIC}<span>${esc(m.commentator)}</span></div>
        </div>
      </article>`;
  }

  function leagueGroup(g) {
    return `
      <section class="league-group">
        <header class="league-header">
          ${g.logo ? `<img class="league-header__logo" src="${esc(g.logo)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}
          <h3 class="league-header__name">${esc(g.league)}</h3>
          <span class="league-header__count">${countLabel(g.matches.length)}</span>
        </header>
        <div class="league-matches">
          ${g.matches.map(matchCard).join('')}
        </div>
      </section>`;
  }

  function showLoading() {
    container.setAttribute('aria-busy', 'true');
    container.innerHTML = `
      <div class="px-loading" role="status">
        <span class="px-spinner"></span>
        <span>جاري تحميل المباريات...</span>
      </div>`;
  }
  function showEmpty() {
    container.setAttribute('aria-busy', 'false');
    container.innerHTML = '<p class="empty">لا توجد مباريات في هذا التاريخ.</p>';
  }
  function showError() {
    container.setAttribute('aria-busy', 'false');
    container.innerHTML = '<div class="error"><p>تعذّر تحميل المباريات حاليًا.</p><button type="button">إعادة المحاولة</button></div>';
    container.querySelector('.error button').addEventListener('click', function () { loadMatches(); });
  }

  function filtered() {
    var list = state.filter === 'all' ? state.matches : state.matches.filter(function (m) { return m.cat === state.filter; });
    var q = searchInput ? searchInput.value.trim().toLowerCase() : '';
    if (q) {
      list = list.filter(function (m) {
        return m.home.name.toLowerCase().indexOf(q) !== -1 || m.away.name.toLowerCase().indexOf(q) !== -1 ||
               m.league.toLowerCase().indexOf(q) !== -1;
      });
    }
    return list;
  }

  function render() {
    if (!state.loaded) return;                              // spinner stays until data is in
    var groups = groupByLeague(filtered());
    if (!groups.length) { showEmpty(); return; }
    container.setAttribute('aria-busy', 'false');
    container.innerHTML = groups.map(leagueGroup).join('');
  }

  function openCard(e) {
    var card = e.target.closest('.match-card.is-link');
    if (card) window.location.href = card.getAttribute('data-href');
  }
  container.addEventListener('click', openCard);
  container.addEventListener('keydown', function (e) { if (e.key === 'Enter') openCard(e); });

  // ------------------------------------------------------------
  // Live matches: minute + channel/commentator from match_info
  // ------------------------------------------------------------
  function applyLiveInfo(m) {
    var info = liveInfoCache[m.id];
    if (!info) return m;
    if (info.minute) m.minute = info.minute;
    if (info.channel && m.channel === 'غير متوفر') m.channel = info.channel;
    if (info.commentator && m.commentator === 'غير متوفر') m.commentator = info.commentator;
    return m;
  }
  async function enrichLive(requestId) {
    var live = state.matches.filter(function (m) { return m.cat === 'live'; }).slice(0, 12);
    if (!live.length) return;
    await Promise.all(live.map(async function (m) {
      try {
        var json = await fetchJson(matchInfoUrl(m.id), 1);
        var d = json && json.data ? json.data : {};
        var cc = Array.isArray(d.channel_commm) && d.channel_commm.length ? d.channel_commm[0] : {};
        liveInfoCache[m.id] = { minute: Number(d.minutes) > 0 ? Number(d.minutes) : 0, channel: cc.channel_name || '', commentator: cc.commentator_name || '' };
      } catch (e) { /* keep the card without minute */ }
    }));
    if (state.requestId !== requestId) return;
    state.matches.forEach(applyLiveInfo);
    render();
  }

  // ------------------------------------------------------------
  // Loading
  // ------------------------------------------------------------
  async function loadMatches(silent) {
    var currentRequest = ++state.requestId;
    if (!silent) { state.loaded = false; showLoading(); }

    if (NOT_CONFIGURED) {                                    // keep the spinner; tell the site owner in the console
      console.error('[PX League] WORKER_BASE_URL is not set: paste your Cloudflare Worker URL into the home page script.');
      return;
    }

    try {
      var json = await fetchJson(matchesUrl(cairoDateString(state.date)));
      if (state.requestId !== currentRequest) return;        // a newer request is running
      var list = Array.isArray(json && json.data) ? json.data : [];
      state.matches = list.map(normalize).map(applyLiveInfo);
      state.loaded = true;
      render();                                              // spinner is replaced only now
      enrichLive(currentRequest);
    } catch (e) {
      if (state.requestId !== currentRequest) return;
      console.warn('[PX League] matches:', e);
      if (silent && state.loaded) return;                    // keep the last good data on refresh errors
      showError();
    }
  }

  // ------------------------------------------------------------
  // UI wiring (tabs, date navigation, search)
  // ------------------------------------------------------------
  function selectTab(t) {
    tabs.forEach(function (tc) { tc.classList.remove('active'); tc.setAttribute('aria-selected', 'false'); });
    t.classList.add('active');
    t.setAttribute('aria-selected', 'true');
    state.filter = t.getAttribute('data-tab') || 'all';
    render();
  }
  tabs.forEach(function (t) {
    t.addEventListener('click', function () { selectTab(t); });
    t.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); selectTab(t); } });
  });

  function changeDay(delta) {
    state.date = new Date(state.date.getTime() + delta * 24 * 60 * 60 * 1000);
    todayLabel.textContent = cairoDateString(state.date);
    loadMatches();
  }
  document.getElementById('prevDay').addEventListener('click', function () { changeDay(-1); });
  document.getElementById('nextDay').addEventListener('click', function () { changeDay(+1); });

  if (searchInput) searchInput.addEventListener('input', render);

  if (location.hash === '#live') { var liveTab = document.querySelector('#matchTabs .tab[data-tab="live"]'); if (liveTab) selectTab(liveTab); }

  todayLabel.textContent = cairoDateString(state.date);
  loadMatches();
  setInterval(function () {
    if (!document.hidden && state.loaded && cairoDateString(state.date) === cairoDateString(new Date())) loadMatches(true);
  }, REFRESH_MS);
})();
